"""Fill in the demo report's explanations, by hand. Task 8.1.

    cd backend
    .venv/Scripts/python scripts/add_demo_explanations.py

Run after `make_demo_report.py`. Reads and rewrites
`frontend/src/demo/report.json` in place.

**These explanations were written by a person, not generated by Claude.**
There is no API budget, so the alternative was a demo with six findings and
six empty explanations -- which would leave tasks 8.6 and 8.7 with nothing to
render and would show nobody what the tool is actually for.

They are written to the same rules the real prompt sets out in
`docs/prompt.md`: `what` is wrong, `who` it affects, a corrected snippet, and
every guess declared in `assumptions`. They are deliberately the *standard*
a real explanation has to meet rather than a flattering sample.

The frontend states that they are hand-written wherever the demo is shown.
That matters more than it might seem: the whole point of task 8.7 is that
people should not trust generated code without reading the assumptions, and a
tool that fudged the provenance of its own demo would be teaching the
opposite lesson.

Keyed by rule id, because the demo page has one instance of each fault.
"""

from __future__ import annotations

import json
import sys
from pathlib import Path

OUT = Path(__file__).resolve().parent.parent.parent / "frontend" / "src" / "demo" / "report.json"

WRITTEN: dict[str, dict] = {
    "button-name": {
        "explanation": {
            "what": (
                "This button contains only an icon, and the icon is correctly hidden from "
                "assistive technology with aria-hidden. Nothing replaces it, so the button "
                "has no name at all."
            ),
            "who": (
                "Someone using a screen reader hears only “button” and has no way to know "
                "what it does short of pressing it to find out. Someone using voice control "
                "cannot click it either, because there is no name to say."
            ),
        },
        "fix": {
            "language": "html",
            "snippet": (
                "<button type=\"button\" aria-label=\"Add item\">\n"
                "  <svg width=\"16\" height=\"16\" viewBox=\"0 0 16 16\" aria-hidden=\"true\" focusable=\"false\">\n"
                "    <path d=\"M2 8h12M8 2v12\" stroke=\"currentColor\" stroke-width=\"2\" fill=\"none\"></path>\n"
                "  </svg>\n"
                "</button>"
            ),
            "assumptions": [
                "Assumed this button adds an item, based on the plus-shaped icon. If it does "
                "something else, change the aria-label to match — the label is what people "
                "hear, so a wrong one is worse than none.",
                "Kept aria-hidden on the icon, which is right once the button has a name: "
                "otherwise the icon would be announced as well and the button read twice.",
            ],
        },
    },
    "image-alt": {
        "explanation": {
            "what": (
                "This image has no alt attribute, so there is nothing to announce in place of "
                "the picture. This is not the same as alt=\"\", which is a valid way to say a "
                "picture is decorative and should be skipped."
            ),
            "who": (
                "Someone using a screen reader hears the filename, or just “image”, and loses "
                "whatever the picture was conveying. The same text appears for everyone else "
                "when the image fails to load on a slow connection."
            ),
        },
        "fix": {
            "language": "html",
            "snippet": "<img src=\"…\" width=\"160\" height=\"80\" alt=\"A plain blue rectangle.\">",
            "assumptions": [
                "The image is an inline SVG of a solid blue rectangle, so this describes "
                "exactly that. A real photograph needs alt text saying what is in it and why "
                "it is on the page — only you can write that.",
                "If this image is purely decorative and the surrounding text already says "
                "everything, use alt=\"\" instead. An empty alt is correct; a missing one is not.",
            ],
        },
    },
    "label": {
        "explanation": {
            "what": (
                "This text box has no label, no aria-label and no title. Nothing names it, so "
                "the field is announced with no indication of what belongs in it."
            ),
            "who": (
                "Someone using a screen reader hears “edit text” and has to guess. Someone "
                "using voice control has no name to say in order to put the cursor there."
            ),
        },
        "fix": {
            "language": "html",
            "snippet": (
                "<label for=\"search-field\">Search</label>\n"
                "<input type=\"text\" id=\"search-field\">"
            ),
            "assumptions": [
                "Assumed this field is for searching, based on its id being “search-field”. "
                "An id is a hint about intent and not a promise — check it matches what the "
                "field actually does.",
                "Used a visible <label> rather than aria-label. Both satisfy the rule, but a "
                "visible label helps everybody, including people who are distracted or "
                "unfamiliar with the form.",
            ],
        },
    },
    "color-contrast": {
        "explanation": {
            "what": (
                "This text is #999999 on a white background, which is a contrast ratio of "
                "about 2.85 to 1. WCAG AA asks for at least 4.5 to 1 for text this size."
            ),
            "who": (
                "Anyone reading in sunlight, on a dimmed screen, on a cheap monitor, or with "
                "any degree of low vision — which, with age, eventually means most people. "
                "Faint grey text is the most common accessibility failure on the web, and it "
                "happens because it looks elegant to someone with good eyes on a good screen."
            ),
        },
        "fix": {
            "language": "css",
            "snippet": ".faded {\n  color: #767676;   /* 4.54:1 on white — passes AA */\n}",
            "assumptions": [
                "Chose the lightest grey that still passes AA at this size, on the assumption "
                "that the faded look is deliberate. #595959 (7:1) would meet the stricter AAA "
                "level if this text matters more than it looks.",
                "Assumed the background stays white. If it changes, the ratio changes with it "
                "and this needs measuring again.",
            ],
        },
    },
    "html-has-lang": {
        "explanation": {
            "what": (
                "The <html> element has no lang attribute, so the page never says what "
                "language it is written in."
            ),
            "who": (
                "Someone using a screen reader hears English read with whatever "
                "pronunciation rules were last in use — English text in a French voice is "
                "near-unintelligible. It also affects automatic translation and how browsers "
                "choose fonts and quotation marks."
            ),
        },
        "fix": {
            "language": "html",
            "snippet": "<html lang=\"en\">",
            "assumptions": [
                "Assumed the page is in English, from its content. Use the code for the "
                "language the page is actually written in — “en-GB” or “hi” or “fr”.",
                "If parts of the page are in another language, mark those individually with "
                "their own lang attribute as well.",
            ],
        },
    },
    "heading-order": {
        "explanation": {
            "what": (
                "This heading is an <h4> directly after an <h2>, skipping level 3. Heading "
                "levels describe how a page is structured, and a skipped level describes a "
                "section that was never opened."
            ),
            "who": (
                "Someone using a screen reader navigates by jumping between headings, the way "
                "a sighted reader skims. A jump from 2 to 4 reads as a missing section, so "
                "they go looking for content that is not there. On screen it looks perfectly "
                "fine, which is why this one gets shipped so often."
            ),
        },
        "fix": {
            "language": "html",
            "snippet": "<h3>This should have been a heading 3</h3>",
            "assumptions": [
                "Assumed this heading belongs directly under the <h2> above it, so <h3> is "
                "the right level. If it is meant to sit under a different section, move it "
                "rather than renumbering.",
                "An <h4> chosen because it looked the right size is better fixed with CSS: "
                "set the level by structure, and the appearance separately.",
            ],
        },
    },
}


def main() -> int:
    if not OUT.is_file():
        print(f"{OUT} not found -- run make_demo_report.py first", file=sys.stderr)
        return 1

    report = json.loads(OUT.read_text(encoding="utf-8"))
    issues = report["issues"]

    missing = [i["rule_id"] for i in issues if i["rule_id"] not in WRITTEN]
    if missing:
        # A new fault in broken.html would otherwise ship with a null
        # explanation and quietly break contract rule 4.
        print(f"no explanation written for: {', '.join(sorted(set(missing)))}", file=sys.stderr)
        return 1

    unused = sorted(set(WRITTEN) - {i["rule_id"] for i in issues})
    if unused:
        print(f"note: written but not in the report: {', '.join(unused)}", file=sys.stderr)

    for issue in issues:
        written = WRITTEN[issue["rule_id"]]
        issue["explanation"] = written["explanation"]
        issue["fix"] = written["fix"]

    # Contract 2.3: the key is present only when explanations are unavailable.
    report["explanations_available"] = True
    report.pop("explanations_unavailable_reason", None)

    OUT.write_text(json.dumps(report, indent=2) + "\n", encoding="utf-8")

    with_assumptions = sum(1 for i in issues if i["fix"]["assumptions"])
    print(f"filled in {len(issues)} explanations and fixes")
    print(f"{with_assumptions} of them declare assumptions")
    print(f"wrote {OUT}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
